code='''from collections import Counter, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = defaultdict(Counter)
    for r in range(3, h):
        for c in range(3, w):
            value = grid[r][c]
            if value != 0:
                counts[r + c][value] += 1

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = counts[r + c].most_common(1)[0][0]
    return out
'''
